// Simulated formulation -> organ model.
// The training data is generated by a rule set I wrote. The directions follow
// published SORT / ApoE findings. Every magnitude is my own assumption.
// Nothing here is experimental data.

export const CLASSES = ['Liver', 'Lung', 'Spleen', 'Brain'] as const

export type SortType = 'none' | 'ionizable' | 'cationic' | 'anionic'

export interface Formulation {
  sort: SortType
  sortMol: number // 0-50 mol%
  size: number // 20-150 nm
  apoe: number // 0-1 ApoE ligand density
  peg: number // 0.5-10 mol%
}

export const N_FEATURES = 7
const HIDDEN = 16

export function toFeatures(f: Formulation): number[] {
  const c = f.sort === 'none' ? 0 : f.sortMol / 50
  return [
    f.sort === 'ionizable' ? 1 : 0,
    f.sort === 'cationic' ? 1 : 0,
    f.sort === 'anionic' ? 1 : 0,
    c,
    (f.size - 20) / 130,
    f.apoe,
    (f.peg - 0.5) / 9.5,
  ]
}

// The assumed rule set. Scores are logits; labels are sampled from softmax.
export function trueScores(x: number[]): number[] {
  const [ion, perm, an, c, sizeN, apoe, pegN] = x
  const liver = 1.5 + 0.8 * ion - 2.0 * perm * c - 1.5 * an * c - 1.0 * apoe * (1 - sizeN)
  const lung = -1.0 + 4.0 * perm * c
  const spleen = -1.0 + 4.5 * an * c + 6.0 * perm * c * (1 - c)
  const brain = -2.0 + 4.0 * apoe * (1 - sizeN) - 0.8 * pegN
  return [liver, lung, spleen, brain]
}

function softmax(z: number[]): number[] {
  const m = Math.max(...z)
  const e = z.map((v) => Math.exp(v - m))
  const s = e.reduce((a, b) => a + b, 0)
  return e.map((v) => v / s)
}

function mulberry32(seed: number) {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export interface Dataset {
  X: number[][]
  y: number[]
  ceiling: number // accuracy of the true rule set's argmax on these labels
}

export function generate(n: number, seed: number): Dataset {
  const rnd = mulberry32(seed)
  const sorts: SortType[] = ['none', 'ionizable', 'cationic', 'anionic']
  const X: number[][] = []
  const y: number[] = []
  let hits = 0
  for (let i = 0; i < n; i++) {
    const sort = sorts[Math.floor(rnd() * 4)]
    const f: Formulation = {
      sort,
      sortMol: sort === 'none' ? 0 : rnd() * 50,
      size: 20 + rnd() * 130,
      apoe: rnd() < 0.5 ? 0 : rnd(),
      peg: 0.5 + rnd() * 9.5,
    }
    const x = toFeatures(f)
    const p = softmax(trueScores(x))
    let u = rnd()
    let label = p.length - 1
    for (let k = 0; k < p.length; k++) {
      u -= p[k]
      if (u <= 0) {
        label = k
        break
      }
    }
    if (p.indexOf(Math.max(...p)) === label) hits++
    X.push(x)
    y.push(label)
  }
  return { X, y, ceiling: hits / n }
}

export interface Net {
  W1: number[][]
  b1: number[]
  W2: number[][]
  b2: number[]
}

function forward(net: Net, x: number[]) {
  const h = net.b1.map((b, j) => {
    let s = b
    for (let i = 0; i < x.length; i++) s += net.W1[j][i] * x[i]
    return Math.tanh(s)
  })
  const z = net.b2.map((b, k) => {
    let s = b
    for (let j = 0; j < h.length; j++) s += net.W2[k][j] * h[j]
    return s
  })
  return { h, p: softmax(z) }
}

export function predict(net: Net, f: Formulation): number[] {
  return forward(net, toFeatures(f)).p
}

export function accuracy(net: Net, d: Dataset): number {
  let ok = 0
  for (let i = 0; i < d.X.length; i++) {
    const p = forward(net, d.X[i]).p
    if (p.indexOf(Math.max(...p)) === d.y[i]) ok++
  }
  return ok / d.X.length
}

export class Trainer {
  net: Net
  epoch = 0
  private m: number[][] = []
  private v: number[][] = []
  private t = 0
  private data: Dataset
  private lr: number
  constructor(data: Dataset, seed = 7, lr = 0.03) {
    this.data = data
    this.lr = lr
    const rnd = mulberry32(seed)
    const g = () => Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd())
    this.net = {
      W1: Array.from({ length: HIDDEN }, () => Array.from({ length: N_FEATURES }, () => g() * 0.5)),
      b1: new Array(HIDDEN).fill(0),
      W2: Array.from({ length: CLASSES.length }, () => Array.from({ length: HIDDEN }, () => g() * 0.3)),
      b2: new Array(CLASSES.length).fill(0),
    }
    const sizes = [HIDDEN * N_FEATURES, HIDDEN, CLASSES.length * HIDDEN, CLASSES.length]
    this.m = sizes.map((s) => new Array(s).fill(0))
    this.v = sizes.map((s) => new Array(s).fill(0))
  }

  // One full-batch Adam step. Returns the mean cross-entropy loss.
  step(): number {
    const { X, y } = this.data
    const n = X.length
    const gW1 = this.net.W1.map((r) => r.map(() => 0))
    const gb1 = this.net.b1.map(() => 0)
    const gW2 = this.net.W2.map((r) => r.map(() => 0))
    const gb2 = this.net.b2.map(() => 0)
    let loss = 0
    for (let i = 0; i < n; i++) {
      const { h, p } = forward(this.net, X[i])
      loss -= Math.log(p[y[i]] + 1e-12)
      const dz = p.map((v, k) => v - (k === y[i] ? 1 : 0))
      const dh = new Array(HIDDEN).fill(0)
      for (let k = 0; k < dz.length; k++) {
        gb2[k] += dz[k]
        for (let j = 0; j < HIDDEN; j++) {
          gW2[k][j] += dz[k] * h[j]
          dh[j] += dz[k] * this.net.W2[k][j]
        }
      }
      for (let j = 0; j < HIDDEN; j++) {
        const da = dh[j] * (1 - h[j] * h[j])
        gb1[j] += da
        for (let f = 0; f < N_FEATURES; f++) gW1[j][f] += da * X[i][f]
      }
    }
    this.t++
    const upd = (params: number[], grads: number[], slot: number) => {
      for (let q = 0; q < params.length; q++) {
        const g = grads[q] / n
        this.m[slot][q] = 0.9 * this.m[slot][q] + 0.1 * g
        this.v[slot][q] = 0.999 * this.v[slot][q] + 0.001 * g * g
        const mh = this.m[slot][q] / (1 - 0.9 ** this.t)
        const vh = this.v[slot][q] / (1 - 0.999 ** this.t)
        params[q] -= (this.lr * mh) / (Math.sqrt(vh) + 1e-8)
      }
    }
    // Flatten views so one update routine handles every tensor.
    const flat = (m: number[][]) => m.flat()
    const unflat = (m: number[][], flatArr: number[]) => {
      let idx = 0
      for (const row of m) for (let c = 0; c < row.length; c++) row[c] = flatArr[idx++]
    }
    const w1 = flat(this.net.W1)
    upd(w1, flat(gW1), 0)
    unflat(this.net.W1, w1)
    upd(this.net.b1, gb1, 1)
    const w2 = flat(this.net.W2)
    upd(w2, flat(gW2), 2)
    unflat(this.net.W2, w2)
    upd(this.net.b2, gb2, 3)
    this.epoch++
    return loss / n
  }
}
